using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class FieldWorldTests
{
 static WorldSession New()=>new(FieldWorld.Create());
 static FieldRequest Request(string id="request:field")=>new(new(id),ContractFixture.Officer,new(25000,15000),new(65000,35000));
 [Fact] public void TerrainSlowsTravelAndBlocksWaterAndCliff(){Assert.Equal(2000,FieldWorld.Speed("road"));Assert.Equal(1000,FieldWorld.Speed("grass"));Assert.Equal(500,FieldWorld.Speed("forest"));Assert.Equal(400,FieldWorld.Speed("slope"));Assert.Equal(0,FieldWorld.Speed("water"));Assert.Equal(0,FieldWorld.Speed("cliff"));Assert.Throws<InvalidDataException>(()=>FieldWorld.Plan(new(5000,5000),new(85000,15000),0));Assert.Throws<InvalidDataException>(()=>FieldWorld.Plan(new(5000,5000),new(45000,65000),0));}
 [Fact] public void FreeFormationUsesExactTargetsAndOwnDetachments(){var s=New();var r=Request() with{A=new(25321,16321),B=new(65321,36321)};Assert.Equal(ResultCode.Accepted,s.SetFormation(r,s.Revision).Code);s.AdvanceTo(2000);for(int i=0;i<3;i++){var v=FieldWorld.Sample(s.DiagnosticSnapshot(),i,s.Seconds);Assert.Equal(new FieldPoint(r.A.X+(r.B.X-r.A.X)*i/2,r.A.Y+(r.B.Y-r.A.Y)*i/2),v.Position);Assert.False(v.Moving);}Assert.Equal(100,s.DiagnosticSnapshot().Units.Where(u=>u.Army==new EntityId("army:officer")).Sum(u=>u.Soldiers));}
 [Fact] public void PathsDetourAroundCliffsWithoutCornerCutting(){var path=FieldWorld.Plan(new(35000,65000),new(55000,65000),0);Assert.True(path.Length>4);Assert.All(path,l=>Assert.True(l.Speed>0));Assert.DoesNotContain(path,l=>l.Terrain is "water" or "cliff");}
 [Fact] public void MidMovementRetargetKeepsExactCurrentPosition(){var s=New();s.SetFormation(Request(),s.Revision);s.AdvanceTo(7);var before=FieldWorld.Sample(s.DiagnosticSnapshot(),0,s.Seconds).Position;Assert.Equal(ResultCode.Accepted,s.SetFormation(Request("request:new") with{A=new(-25000,15000),B=new(-25000,35000)},s.Revision).Code);Assert.Equal(before,FieldWorld.Sample(s.DiagnosticSnapshot(),0,s.Seconds).Position);}
 [Fact] public void InvalidFormationIsAtomicAndCannotControlOtherForces(){var s=New();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.SetFormation(Request() with{Actor=ContractFixture.Lord},s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.SetFormation(Request() with{A=new(85000,5000)},s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact] public void IdempotencyAndRevisionPreventDuplicateCommands(){var s=New();var r=Request();s.SetFormation(r,s.Revision);Assert.Equal(ResultCode.AlreadyAccepted,s.SetFormation(r,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.SetFormation(r with{B=new(55000,25000)},s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.SetFormation(Request("request:stale"),0).Code);}
 [Theory][InlineData(1)][InlineData(17)][InlineData(40)][InlineData(2000)] public void SaveRestoreContinuesIdenticalTerrainPathsAndPositions(long at){var s=New();s.SetFormation(Request(),s.Revision);s.AdvanceTo(at);var root=Path.Combine(Path.GetTempPath(),"field-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,FieldWorld.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));host.Current.SetPaused(false);s.AdvanceTo(3000);host.Current.AdvanceTo(3000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Field),ContractJson.Write(host.Current.DiagnosticSnapshot().Field));for(int i=0;i<3;i++)Assert.Equal(FieldWorld.Sample(s.DiagnosticSnapshot(),i,3000),FieldWorld.Sample(host.Current.DiagnosticSnapshot(),i,3000));}
 [Fact] public void FixedSeaRulesAndOldSavesStaySeparate(){var w=FieldWorld.Create();Assert.Equal(TravelWorld.Departure(TrafficWorld.Create(),"nation-sakai-sumoto",123),TravelWorld.Departure(w,"nation-sakai-sumoto",123));Assert.Equal(NationalRoutes.Edges,BranchRoutes.GraphEdges(w));Assert.Empty(w.Field!.Orders);}
 [Fact] public void MissingFieldAndTamperedTerrainPathAreRejected(){var s=New();s.SetFormation(Request(),s.Revision);var w=s.DiagnosticSnapshot();var o=w.Field!.Orders[0];var routes=o.Routes.ToArray();var legs=routes[0].Legs.ToArray();legs[0]=legs[0] with{Speed=9999};routes[0]=routes[0] with{Legs=legs};w.Field=new([o with{Routes=routes}]);Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=s.DiagnosticSnapshot();w.Field=null;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
 [Fact] public void RoadsAreFasterThanEqualDistanceGrass(){var road=FieldWorld.Plan(new(5000,5000),new(35000,5000),0);var grass=FieldWorld.Plan(new(-45000,-35000),new(-15000,-35000),0);Assert.True(road[^1].EndAt<grass[^1].EndAt);}
 [Fact] public void NationalSeaJourneyRemainsAvailableInNewRuleset(){var s=New();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:sea","sumoto"),s.Revision).Code);s.AdvanceTo(1000000);Assert.Equal(new EntityId("site:sumoto"),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Contains(s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs,l=>NationalRoutes.Sea(l.Edge));}
 [Fact] public void ReturningToRoadAnchorAllowsNationalTravelAndReenteringField(){var s=New();s.SetFormation(Request(),s.Revision);s.AdvanceTo(400);s.SetFormation(new(new("request:return"),ContractFixture.Officer,new(5000,5000),new(5000,25000)),s.Revision);s.AdvanceTo(800);Assert.Equal(ContractFixture.Castle,s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:national","sakai"),s.Revision).Code);s.AdvanceTo(1000000);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:back","castle"),s.Revision).Code);s.AdvanceTo(2000000);Assert.Equal(ResultCode.Accepted,s.SetFormation(Request("request:again"),s.Revision).Code);s.AdvanceTo(2000400);Assert.Equal(LocationKind.AtPosition,s.GetActorView(ContractFixture.Officer).Location.Kind);}
}
